{
  "Microsoft": {
    "detectors": [
      {
        "presentMatcher": [
          {
            "type": "css",
            "target": {
              "selector": "#wcpConsentBannerCtrl, #wcpCookiePreferenceCtrl"
            }
          }
        ],
        "showingMatcher": [
          {
            "type": "css",
            "target": {
              "selector": "#wcpConsentBannerCtrl, #wcpCookiePreferenceCtrl",
              "displayFilter": true
            }
          }
        ]
      }
    ],
    "methods": [
      {
        "name": "HIDE_CMP",
        "action": {
          "type": "hide",
          "target": {
            "selector": "#wcpConsentBannerCtrl, #wcpCookiePreferenceCtrl"
          }
        }
      },
      {
        "name": "OPEN_OPTIONS",
        "action": {
          "type": "click",
          "parent": {
            "selector": "#wcpConsentBannerCtrl"
          },
          "target": {
            "selector": "button",
            "textFilter": "Manage cookies"
          }
        }
      },
      {
        "name": "DO_CONSENT",
        "action": {
          "type": "list",
          "actions": [
            {
              "type": "waitcss",
              "target": {
                "selector": "#wcpCookiePreferenceCtrl dt[aria-label=\"Analytics\"]"
              },
              "retries": 10,
              "waitTime": 250
            },
            {
              "type": "consent",
              "consents": [
                {
                  "type": "B",
                  "trueAction": {
                    "type": "click",
                    "parent": {
                      "selector": "#wcpCookiePreferenceCtrl"
                    },
                    "target": {
                      "selector": "dt[aria-label=\"Analytics\"] input[value=\"accept\"]"
                    }
                  },
                  "falseAction": {
                    "type": "click",
                    "parent": {
                      "selector": "#wcpCookiePreferenceCtrl"
                    },
                    "target": {
                      "selector": "dt[aria-label=\"Analytics\"] input[value=\"reject\"]"
                    }
                  }
                },
                {
                  "type": "F",
                  "trueAction": {
                    "type": "list",
                    "actions": [
                      {
                        "type": "click",
                        "parent": {
                          "selector": "#wcpCookiePreferenceCtrl"
                        },
                        "target": {
                          "selector": "dt[aria-label=\"Social Media\"] input[value=\"accept\"]"
                        }
                      },
                      {
                        "type": "click",
                        "parent": {
                          "selector": "#wcpCookiePreferenceCtrl"
                        },
                        "target": {
                          "selector": "dt[aria-label=\"Advertising\"] input[value=\"accept\"]"
                        }
                      }
                    ]
                  },
                  "falseAction": {
                    "type": "list",
                    "actions": [
                      {
                        "type": "click",
                        "parent": {
                          "selector": "#wcpCookiePreferenceCtrl"
                        },
                        "target": {
                          "selector": "dt[aria-label=\"Social Media\"] input[value=\"reject\"]"
                        }
                      },
                      {
                        "type": "click",
                        "parent": {
                          "selector": "#wcpCookiePreferenceCtrl"
                        },
                        "target": {
                          "selector": "dt[aria-label=\"Advertising\"] input[value=\"reject\"]"
                        }
                      }
                    ]
                  }
                }
              ]
            }
          ]
        }
      },
      {
        "name": "SAVE_CONSENT",
        "action": {
          "type": "list",
          "actions": [
            {
              "type": "wait",
              "waitTime": 500
            },
            {
              "type": "click",
              "parent": {
                "selector": "#wcpCookiePreferenceCtrl"
              },
              "target": {
                "selector": "[aria-label=\"Save changes\"]"
              }
            }
          ]
        }
      }
    ]
  }
}
